def price_stream(start, drift, n):
    """Yield n simulated prices, each drifting up by a fixed factor."""
    price = start
    for _ in range(n):
        yield price
        price *= 1 + drift

for p in price_stream(100.0, 0.01, 3):
    print(round(p, 2))     # 100.0, 101.0, 102.01 - one per line

import functools
import time

def timed(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f'{func.__name__}: {elapsed:.6f}s')
        return result
    return wrapper

@timed
def total_notional(trades):
    return sum(qty * price for _, qty, price in trades)

trades = [('AAPL', 250, 42.25), ('MSFT', 100, 43.50)]
print(total_notional(trades))
# total_notional: 0.000012s   <- timing varies between runs
