import functools

def counted(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

@counted
def value(qty, price):
    return qty * price

print(value(250, 42.25))   # 10562.5
print(value(100, 43.50))   # 4350.0
print(value.calls)         # 2
```
The wrapper intercepts every call, increments the counter stored on the wrapper object itself, and returns the true product - two calls, so value.calls prints 2.

